"""Pro-site curriculum reconciliation. Sources preserved alongside this script."""
import json,re
from pathlib import Path
root=Path(__file__).parent
originals={p['id']:p for fp in root.glob('originals-*.json') for p in json.loads(fp.read_text())}
updates={}
dashboard='/pro-analytics/'
def P(s):return '<p>'+s+'</p>'
def H(s):return '<h2>'+s+'</h2>'
def L(items,ordered=False):
 tag='ol' if ordered else 'ul'
 return '<'+tag+'>'+''.join('<li>'+x+'</li>' for x in items)+'</'+tag+'>'
def table(headers,rows):
 return '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr>'+''.join('<th style="background:#074b78;color:white;padding:12px;text-align:left">'+v+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td style="border:1px solid #cbdde8;padding:12px;vertical-align:top">'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def intro(label):return '<p style="color:#074b78;font-weight:700">Live Campaign · Pro Analytics · Business application</p>'+H(label)
def links():return P('<a href="/pro-analytics/">Open Pro Analytics Dashboard</a> · <a href="/?page_id=3066">Setup and Quick Start</a>')
def task(items):return H('Put It to Work')+L(items,True)
def setpage(id,title,body,keep_video=False):
 original=originals[id]
 video=''
 if keep_video:
  m=re.search(r'<div style="padding: 56\.25%.*?</div>',original['html'],re.S)
  if m: video='<details><summary>Foundation lecture — earlier edition</summary>'+P('This recording explains the SMM foundation. Its software screens and setup steps may show an earlier edition. Use the current Pro Analytics instructions on this page for reporting.')+m.group()+'</details>'
 updates[id]={'id':id,'title':title,'html':intro(title.split(' ',1)[1] if re.match(r'^\d',title) else title)+body+video+links(),'url':original['links'][0]}
def add(id,body):
 original=originals[id]
 updates[id]={'id':id,'title':original['title'],'html':original['html']+'\n<section class="smm-pro-application">'+H('Apply This with Pro Analytics')+body+links()+'</section>','url':original['links'][0]}

setpage('1265','7.1 Preparing to Track the Campaign',
 P('Your Brand is the foundation. The Message Matrix turns that foundation into a focused campaign: a defined audience, serialized content and a useful path from each channel back to your website. Before publishing, decide what you want that audience to do and how you will recognize progress.')+
 P('Pro Analytics brings supported website, email and social reporting into your company workspace on Social Media Magnet Pro. It does not require the old weekly-post plugin or access-token handshake on your customer website. Your website still needs working GA4 tracking; authorizing a connection does not install it.')+
 H('Start with a Business Question')+L(['<strong>Awareness:</strong> Is useful content reaching the audience we intend to serve?','<strong>Acquisition:</strong> Are our spokes bringing relevant visitors into the Brand hub?','<strong>Retention:</strong> Are people returning, and does email give them a useful reason to come back?','<strong>Action:</strong> Are the intended form or phone events occurring, and what do they actually count?'])+
 H('Prepare the Workspace')+L(['Open Pro Analytics and confirm the company. Owners working across companies should check the company name before every connection or report.','In Account, save the website, logo, social profiles and intended service area. A saved profile link does not authorize that platform. A location entry records your market; it does not apply a geography filter.','The Owner connects the correct GA4 property, selects Mailchimp or Constant Contact when used, and authorizes the intended Facebook Page and linked professional Instagram account when available. Confirm the displayed account names after saving.','Confirm the event names used for forms and phone actions. Test the intended action with your website/analytics administrator before relying on the totals.','Choose a baseline period and a reporting timezone. Record launch dates and meaningful changes in the publishing calendar.','Invite only the people who need company access. Owners manage connections and team access; Owners and Analysts can request Reviews when enabled. Viewers can read shared results.'],True)+
 P('The four Brand elements—Story, Promise, Belief and Trust—remain your reference for every decision. A larger audience is useful only when your content and next action strengthen the relationship you are trying to build.'),True)

setpage('1268','7.2 Platform Insights for Social Acquisition',
 P('Social content is an acquisition spoke. It should connect an audience question to your Brand, then give interested people a useful next step. Start with what the post says and where it leads; use the numbers to understand how that message is traveling.')+
 H('Read Each Signal for What It Measures')+table(['Signal','What to Look For'],[
 ('Likes and followers','Audience size and its reported change. A current total is different from new follows or net growth during a period; use the label shown.'),
 ('Views or impressions','Visibility and exposure under the platform’s definition. These are not necessarily unique people, and views are not the same as reach.'),
 ('Reactions, comments, shares and saves','Available engagement actions. Read the actual responses for meaning; a count alone does not measure positive sentiment.'),
 ('Website visits and goal events','What happened at the hub when attribution and tracking are available. Social views, website sessions and sales are different measures.')])+
 H('Use the Top Posts as Content Clues')+P('Review the top-five posts shown for the connected Facebook or Instagram account. Check the date, format, topic, hook and destination. Post view counts may be lifetime totals for posts published in the selected period, rather than views earned only during that period. Older posts have had more time to accumulate activity.')+
 P('A high-view post is a visibility signal worth investigating. A low result is a prompt to inspect content and exposure, not a verdict on the Brand. Compare similar formats and observation time, and use the platform’s native insights for engagement details that Pro Analytics does not supply.')+
 task(['Choose one stronger and one weaker post aimed at the same audience.','Identify the Message Matrix bucket and the Brand element each post supports.','Check whether the hook, image and linked hub page carry the same idea.','Develop the useful theme, Reframe the weak handoff or Create a missing dimension. Put the next sequence into the publishing calendar.'])+
 P('Direct reporting connections currently cover supported Facebook Page and professional Instagram reporting. Visits from other social sources can still appear in website analytics; that does not mean every social platform is directly connected. This review process focuses on organic content; paid activity should be assessed separately.'))

setpage('1273','7.3 Pro Analytics: Traffic Coming into the Website',
 P('Open Pro Analytics → Dashboard → Report. Confirm the company, then choose the dates that answer your question. The Report is a selected-period view of your campaign, rather than the old cumulative weekly grading report.')+
 H('Select Dates and Compare')+L(['Choose 30, 60 or 90 days, one year, or a custom range.','Set Compare with to <strong>None</strong>, <strong>Prior period</strong> or <strong>Previous year</strong>. None shows the selected period without a directional comparison.','Select Apply dates and wait for the report to finish. A changed field is not a completed refresh. Read the visible progress, missing-data or error message before interpreting results.','Confirm the displayed dates, comparison and timezone. Use the same selection when printing or sharing.'],True)+
 H('Follow the Traffic Back to the Message')+table(['Source','Interpretation'],[
 ('Organic Search','Visits attributed to unpaid search results. Inspect the content and customer question behind the visit.'),
 ('Social','Visits attributed to social channels. Compare the relevant post, link and hub destination.'),
 ('Email','Visits attributed to an email campaign. Consistent campaign tags help distinguish the return path.'),
 ('Referral','Visits attributed to links on other websites.'),
 ('Direct / unattributed','The source is not clear. This can include typed/bookmarked visits and missing referral information; do not assign all Direct traffic to email or Brand awareness.')])+
 P('Use Sources and Timeline to see which channels contribute and when activity changes. A percentage should always be read with its count: growth from two visits to four is 100%, but it is still four visits. Check whether a comparison period had different publishing activity or a seasonal event.')+
 H('Read the Matrix as Direction')+P('The dashboard plots session change vertically and change in the returning-to-new-user ratio horizontally. Goal events per 100 sessions are shown separately. These signals help you inspect acquisition and retention balance; they do not directly measure loyalty, sentiment or the reason a person returned. With Compare None, a centered marker does not prove ideal Brand alignment.')+
 H('Filtering and Missing Data')+P('GA4 automatically excludes known bots, but does not supply the excluded volume. Additional bot screening and service-area filtering are not active in this implementation. Saved service locations do not remove out-of-market visits. Unavailable data is not zero, and geography alone does not identify a bot.')+
 task(['Save a Report for one meaningful period.','Identify the largest relevant source and one change over time.','Inspect the actual message and destination before changing the campaign.','Use Print / Save for the completed Report; retain the company, report type and timestamp in its filename.']))

setpage('1278','7.4 Pro Analytics and GA4: Behavior Within the Website',
 P('Getting someone to your website is the handoff, not the finish line. The hub page should continue the promise made in the social post or email and make the next useful action clear.')+
 H('Keep the Measures Distinct')+L(['<strong>User:</strong> a measured visitor identity under the analytics system, not a verified customer.','<strong>Session:</strong> a group of interactions during a visit; one person can have multiple sessions.','<strong>Page view:</strong> a viewing event; repeated views can count again.','<strong>Entry page:</strong> where a session begins, which is different from the most-viewed page overall.','<strong>New and returning:</strong> analytics classifications that depend on available identifiers; a returning visitor is not automatically a loyal customer.'])+
 H('Use Pro for Direction, GA4 for a Deeper Look')+P('Start with Report → Audience and the website totals. Age appears on the left and gender on the right; geography and device are different groups. Demographic reporting may cover only a subset, be withheld or show Unknown. Do not treat it as a complete profile of your customers.')+
 P('For page rankings, landing pages, engagement-time metrics and detailed journeys, open the connected property in GA4 and use its available Reports or Explorations. The current native Pro Report does not yet provide top-page/blog rankings, engagement duration or automatic funnel visualization. Use GA4 for these tasks rather than looking for a missing Pro control.')+
 H('Inspect the Actual Hub Page')+L(['Does the headline answer the question raised by the spoke?','Does the content demonstrate the Brand Promise and support Belief and Trust?','Is the next action appropriate for a first-time or returning visitor?','Does the page work on a phone, and do links and forms function?','For the SMM publishing model, blog content uses the <strong>/blog/</strong> path. Use that path to isolate blog content in GA4; do not assume every customer platform already follows it.'])+
 P('There is no universal time-on-site target that proves success. A short visit can answer a simple question, while a long visit can reflect useful reading or confusion. A popular homepage is not by itself evidence of a failed acquisition strategy. Compare the intended journey with what the available evidence supports.')+
 task(['Choose one campaign destination.','Inspect its landing-page and event evidence in GA4 for the same dates as the Pro Report.','Fix one message-to-action handoff and record the change date.']))

setpage('1285','7.5 GA4 Events and the Goal Funnel',
 P('A goal funnel describes the useful steps you want someone to take: arrive at relevant content, consider the offer and complete an intended action. GA4 uses event-based measurement. The old Universal Analytics View → Goals → Destination setup no longer applies.')+
 H('Define the Action Before Counting It')+L(['Name the business outcome: an enquiry, appointment request, newsletter signup or another useful next step.','Identify the event that represents it. A phone-link click is not a completed call; a form event is not automatically a qualified lead or sale.','Ask your website/analytics administrator to configure and verify that event in the correct GA4 property. Confirm that it fires for the intended action and does not fire repeatedly merely because a thank-you page is refreshed.','Use GA4 Realtime or DebugView as appropriate to verify collection. Mark an important event as a key event in GA4 when that is the intended reporting definition.','Confirm which form and phone event names Pro Analytics uses. GA4 key-event totals and Pro’s configured event counts are not automatically the same.'],True)+
 H('Understand the Pro Metric')+P('<strong>Goal events per 100 sessions = (configured form events + configured phone events) ÷ sessions × 100.</strong>')+
 P('This is an event-frequency measure, not the percentage of people who became customers. One session can contain more than one event, so the value can exceed 100. Keep form and phone definitions consistent between periods and investigate a tracking change before attributing a jump to better messaging.')+
 table(['Illustrative period','Sessions','Form + phone events','Events / 100 sessions'],[('Previous','1,000','60','6.0'),('Current','1,200','54','4.5')])+
 P('Traffic increased 20%, but events per 100 sessions fell from 6.0 to 4.5—a 25% relative decline. That is a reason to inspect the handoff and tracking. It does not prove a broken form or a rejected Brand.')+
 H('Find Friction in GA4')+P('Use a separately configured GA4 Funnel exploration when you need step-by-step drop-off analysis. Define the steps, sequence and whether the funnel is open or closed before interpreting it. Pro Analytics does not currently build this funnel automatically.')+
 task(['Choose one acquisition action and one useful return-visit action.','Document the event definition and verification for each.','Check the form, phone link or destination on desktop and mobile.','If results weaken, inspect the content, next action and technical tracking before making a change.']))

setpage('1290','7.6 Email Statistics for Consumer Retention',
 P('Email is the return path in the Social Media Magnet. It should give an audience that already knows you a useful reason to revisit the Brand hub. Keep the 2+2+2 content approach and connect each message to a deliberate content focus and destination.')+
 H('Connect the Provider You Use')+P('The company Owner selects Mailchimp or Constant Contact in Account and completes the connection shown there. Confirm the provider and audience/account after saving. A disconnected provider or unavailable result is not evidence of zero response.')+
 H('Read Counts and Rates Together')+L(['<strong>Subscribers:</strong> audience size as labeled; distinguish a current total from additions or losses during a period.','<strong>Sent and delivered:</strong> related but different counts. Use the provider’s definition when comparing campaigns.','<strong>Opens:</strong> tracked opening activity, which privacy protections and automated activity can distort. An open does not prove the message was read.','<strong>Clicks:</strong> distinguish total clicks from unique recipients who clicked. Automated link checks can also affect these counts.','<strong>Rates:</strong> retain the denominator shown by the provider. Do not average percentages across campaigns without their underlying counts.'])+
 P('The selected email range identifies campaigns by send date. Their displayed responses may be lifetime-to-date responses for those campaigns. A message sent near the end of the range has had less time to collect activity. Do not describe every displayed open or click as having occurred within the selected date range.')+
 H('Connect the Email to the Hub')+P('Use consistent campaign tags on email links. Compare attributable Email visits and the intended website action with provider clicks, allowing for differences in tracking and consent. Direct traffic has no clear attribution; do not add it all to Email or describe it as forwarded mail.')+
 task(['Review the overall totals, then select one stronger and one weaker email with comparable response time.','Inspect the subject, opening hook, content focus and next step.','Choose one change to the message or destination.','Record the send date and review it alongside the same-period website evidence.']))

